def bh_fdr(pvals):
    p = np.asarray(pvals, dtype=float)
    m = p.size
    if m == 0:
        return p
    order = np.argsort(p)
    ranked_p = p[order]
    q = ranked_p * m / (np.arange(m) + 1)
    q = np.minimum.accumulate(q[::-1])[::-1]
    q[q > 1] = 1
    out = np.empty_like(q)
    out[order] = q
    return out

def load_sparse_csr(npz_path):
    loader = np.load(npz_path)
    data = loader['data']
    indices = loader['indices']
    indptr = loader['indptr']
    shape = loader['shape']
    return sp.csr_matrix((data, indices, indptr), shape=shape)

def row_l2_normalize(X):
    X = np.asarray(X, dtype=float)
    norms = np.linalg.norm(X, axis=1, keepdims=True)
    norms[norms == 0] = 1.0
    return X / norms

def mean_pairwise_ari(label_list):
    k = len(label_list)
    if k < 2:
        return 1.0
    s = 0.0
    n = 0
    for i in range(k):
        for j in range(i + 1, k):
            s += adjusted_rand_score(label_list[i], label_list[j])
            n += 1
    return float(s / max(n, 1))

def per_domain_standardize_train_stats(X, domains, mask_train):
    # standardize per-domain using train statistics only, apply to all cells
    X_out = X.copy()
    doms = np.unique(domains)
    for d in doms:
        idx_all = (domains == d)
        idx_tr = idx_all & mask_train
        if np.sum(idx_tr) == 0:
            continue
        mu = X[idx_tr].mean(axis=0)
        sd = X[idx_tr].std(axis=0, ddof=0)
        sd[sd == 0] = 1.0
        X_out[idx_all] = (X[idx_all] - mu) / sd
    return X_out

def fast_silhouette(X, labels, metric='euclidean', max_samples=5000, random_state=42):
    n = X.shape[0]
    if n <= 1000:
        try:
            return float(silhouette_score(X, labels, metric=metric))
        except Exception:
            return -1.0
    rng = np.random.default_rng(random_state)
    idx = rng.choice(n, size=min(max_samples, n), replace=False)
    X_sub = X[idx]
    labels_sub = np.array(labels)[idx]
    if len(np.unique(labels_sub)) < 2:
        return -1.0
    try:
        return float(silhouette_score(X_sub, labels_sub, metric=metric))
    except Exception:
        return -1.0

def build_variants(emb, splits, domains):
    mask_train = (splits == 'train')
    variants = {}

    # Global standardization using train only
    scaler_global = StandardScaler(with_mean=True, with_std=True)
    X_std_tr = scaler_global.fit_transform(emb[mask_train, :])
    X_std = emb.copy()
    X_std[mask_train, :] = X_std_tr
    X_std[~mask_train, :] = scaler_global.transform(emb[~mask_train, :])
    variants['global'] = {
        'X_euc': X_std.copy(),
        'X_cos': row_l2_normalize(X_std.copy()),
        'info': {'scaler': 'train_global', 'per_domain': False, 'whiten': False}
    }

    # Per-domain standardization using train stats
    X_dom = per_domain_standardize_train_stats(X_std, domains=np.array(domains), mask_train=mask_train)
    variants['domain'] = {
        'X_euc': X_dom.copy(),
        'X_cos': row_l2_normalize(X_dom.copy()),
        'info': {'scaler': 'train_global', 'per_domain': True, 'whiten': False}
    }

    # PCA whitening on global standardized using train only
    try:
        pca = PCA(whiten=True, random_state=42)
        Xw_tr = pca.fit_transform(X_std[mask_train, :])
        Xw = np.zeros_like(X_std, dtype=float)
        Xw[mask_train, :] = Xw_tr
        Xw[~mask_train, :] = pca.transform(X_std[~mask_train, :])
        variants['whiten_global'] = {
            'X_euc': Xw.copy(),
            'X_cos': row_l2_normalize(Xw.copy()),
            'info': {'scaler': 'train_global', 'per_domain': False, 'whiten': True}
        }
    except Exception:
        pass

    return variants

def leiden_search(X_train, y_true_train, metric, nn_grid, seed_list, res_min=0.2, res_max=2.0, res_step=0.2):
    best = None
    # coarse grid
    ad_tr = ad.AnnData(X=X_train.copy())
    for nn in nn_grid:
        try:
            sc.pp.neighbors(ad_tr, n_neighbors=nn, metric=metric, random_state=42, use_rep=None)
        except Exception:
            continue
        res_values = np.arange(res_min, res_max + 1e-8, res_step)
        for res in res_values:
            labels_by_seed = []
            ari_by_seed = []
            sil_by_seed = []
            for sd in seed_list:
                key = f'leiden_r{res:.2f}_s{sd}'
                try:
                    sc.tl.leiden(ad_tr, resolution=float(res), key_added=key, random_state=int(sd))
                    labs = ad_tr.obs[key].astype(str).values
                except Exception:
                    continue
                if len(np.unique(labs)) < 2:
                    ari = -1.0
                    sil = -1.0
                else:
                    ari = float(adjusted_rand_score(y_true_train, labs))
                    sil = fast_silhouette(X_train, labs, metric=metric, max_samples=5000, random_state=42)
                labels_by_seed.append(labs)
                ari_by_seed.append(ari)
                sil_by_seed.append(sil)
            if len(ari_by_seed) == 0:
                continue
            mean_ari = float(np.nanmean(ari_by_seed))
            stab = mean_pairwise_ari(labels_by_seed)
            best_seed_idx = int(np.nanargmax(ari_by_seed))
            rec = {
                'algo': 'leiden',
                'params': {'n_neighbors': int(nn), 'resolution': float(res), 'seed': int(seed_list[best_seed_idx])},
                'labels_train': labels_by_seed[best_seed_idx],
                'ari_train': float(ari_by_seed[best_seed_idx]),
                'sil_train': float(sil_by_seed[best_seed_idx]),
                'stability': float(stab),
                'metric': metric
            }
            if (best is None) or (rec['ari_train'] > best['ari_train']) or (math.isclose(rec['ari_train'], best['ari_train']) and rec['sil_train'] > best['sil_train'])):
                best = rec

    # fine zoom around best resolution if available
    if best is not None:
        nn = best['params']['n_neighbors']
        res0 = best['params']['resolution']
        res_values = np.arange(max(0.2, res0 - 0.1), min(2.0, res0 + 0.1) + 1e-8, 0.05)
        ad_tr = ad.AnnData(X=X_train.copy())
        try:
            sc.pp.neighbors(ad_tr, n_neighbors=nn, metric=metric, random_state=42, use_rep=None)
        except Exception:
            return best
        for res in res_values:
            labels_by_seed = []
            ari_by_seed = []
            sil_by_seed = []
            for sd in seed_list:
                key = f'leiden_r{res:.2f}_s{sd}'
                try:
                    sc.tl.leiden(ad_tr, resolution=float(res), key_added=key, random_state=int(sd))
                    labs = ad_tr.obs[key].astype(str).values
                except Exception:
                    continue
                if len(np.unique(labs)) < 2:
                    ari = -1.0
                    sil = -1.0
                else:
                    ari = float(adjusted_rand_score(y_true_train, labs))
                    sil = fast_silhouette(X_train, labs, metric=metric, max_samples=5000, random_state=42)
                labels_by_seed.append(labs)
                ari_by_seed.append(ari)
                sil_by_seed.append(sil)
            if len(ari_by_seed) == 0:
                continue
            mean_ari = float(np.nanmean(ari_by_seed))
            stab = mean_pairwise_ari(labels_by_seed)
            best_seed_idx = int(np.nanargmax(ari_by_seed))
            rec = {
                'algo': 'leiden',
                'params': {'n_neighbors': int(nn), 'resolution': float(res), 'seed': int(seed_list[best_seed_idx])},
                'labels_train': labels_by_seed[best_seed_idx],
                'ari_train': float(ari_by_seed[best_seed_idx]),
                'sil_train': float(sil_by_seed[best_seed_idx]),
                'stability': float(stab),
                'metric': metric
            }
            if (rec['ari_train'] > best['ari_train']) or (math.isclose(rec['ari_train'], best['ari_train']) and rec['sil_train'] > best['sil_train'])):
                best = rec
    return best

