    # Collect alternate targets from environment/unknowns to mirror outputs if needed
    def collect_alt_targets(primary_path, key_name, unknown_tokens):
        cands = []
        for k in [key_name, key_name.upper(), f"{key_name}_path", f"{key_name.upper()}_PATH"]:
            v = os.environ.get(k)
            if isinstance(v, str):
                vv = v.strip()
                if vv and vv.lower() not in ('none', 'null', 'nil'):
                    cands.append(vv)
        unk = list(unknown_tokens) if unknown_tokens is not None else []
        for i, tok in enumerate(unk):
            if not isinstance(tok, str):
                continue
            # support --key=value style
            if tok.startswith("--") and "=" in tok:
                kpart, vpart = tok.lstrip('-').split('=', 1)
                key = kpart.replace('-', '_').lower()
                # accept '*_path' alias
                if key == key_name or key == f"{key_name}_path":
                    val = vpart.strip()
                    if val:
                        cands.append(val)
            key = tok.lstrip('-').replace('-', '_').lower()
            if key == key_name or key == f"{key_name}_path":
                if (i + 1) < len(unk):
                    val = unk[i + 1]
                    if isinstance(val, str) and val.strip():
                        cands.append(val.strip())
            # token that itself is the path
            if os.path.splitext(tok)[1].lower() in ('.csv', '.json', '.png'):
                # heuristic match by filename
                if os.path.basename(tok).lower() == f"{key_name}.csv" or os.path.basename(tok).lower() == f"{key_name}.json" or os.path.basename(tok).lower() == f"{key_name}.png":
                    cands.append(tok)
