                else:
                    labs = np.array(['0'] * n_sel)
                ari = -1.0
                sil = fast_silhouette(X_sel_use, labs, metric='cosine', max_samples=3000, random_state=42) if len(np.unique(labs)) > 1 else -1.0
                best_overall = {
                    'algo': 'kmeans',
                    'params': {'k': int(max(k_fb, 1))},
                    'model': None,
                    'labels_train': np.asarray(labs).astype(str),
                    'ari_train': ari,
                    'sil_train': sil,
                    'stability': 1.0,
                    'metric': 'cosine',
                    'variant': 'global'
                }
