            chosen_variant = best_overall['variant']
            chosen_metric = best_overall['metric']
            X_all_use = (variants[chosen_variant]['X_cos'] if chosen_metric == 'cosine' else variants[chosen_variant]['X_euc'])
            X_sel_use = X_all_use[mask_sel, :]
            X_anchor_use = X_all_use[mask_anchor, :]
            X_query_use = X_all_use[~mask_anchor, :]

            # Fit on anchors and get labels
            algo = best_overall['algo']
            params = best_overall['params']
            if algo == 'kmeans':
                k_target = int(params.get('k', 10))
                k_fit = int(min(max(1, k_target), max(1, X_anchor_use.shape[0])))
                if k_fit >= 2 and X_anchor_use.shape[0] >= 2:
