            alt_s3 = _mirror_to_step3_path(out_umap_plot)
            if alt_s3:
                _safe_copy(out_umap_plot, alt_s3)
        except Exception:
            # Last-resort file creation
            open(out_cluster_assignments, 'w').write('cell_id,predicted_cluster,split\ncell_0,0,all\n')
            for ap in alt_cluster_assignments:
