def write_dummy_png(path):
    import base64
    png_b64 = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMB/akS0l4AAAAASUVORK5CYII='
    data = base64.b64decode(png_b64)
