def bh_fdr(pvals):
    p = np.asarray(pvals, dtype=float)
    m = p.size
    if m == 0:
        return p
    order = np.argsort(p)
    ranked = p[order]
    q = ranked * m / (np.arange(m) + 1)
    q = np.minimum.accumulate(q[::-1])[::-1]
    q[q > 1] = 1
    out = np.empty_like(q)
    out[order] = q
    return out

def load_sparse_csr(npz_path):
    loader = np.load(npz_path)
    return sp.csr_matrix((loader['data'], loader['indices'], loader['indptr']), shape=loader['shape'])

def row_l2_normalize(X):
    X = np.asarray(X, dtype=float)
    nrm = norm(X, axis=1, keepdims=True)
    nrm[nrm == 0] = 1.0
    return X / nrm

def fast_silhouette(X, labels, metric='euclidean', max_samples=5000, random_state=42):
    n = X.shape[0]
    if len(np.unique(labels)) < 2:
        return -1.0
    if n <= 3000:
        try:
            return float(silhouette_score(X, labels, metric=metric))
        except Exception:
            return -1.0
    rng = np.random.default_rng(random_state)
    idx = rng.choice(n, size=min(max_samples, n), replace=False)
    try:
        return float(silhouette_score(X[idx], np.array(labels)[idx], metric=metric))
    except Exception:
        return -1.0

def asw_batch(X, batch_labels, metric='euclidean'):
    labs = np.asarray(batch_labels).astype(str)
    if len(np.unique(labs)) < 2 or X.shape[0] < 3:
        return 0.0
    try:
        return float(silhouette_score(X, labs, metric=metric))
    except Exception:
        return 0.0

def load_embeddings(adata):
    n = adata.n_obs
    splits = adata.obs['split'].astype(str).values if 'split' in adata.obs.columns else np.array(['all'] * n)
    masks = {
        'train': (splits == 'train'),
        'val': (splits == 'val'),
        'test': (splits == 'test')
    }
    emb = None
    dims = None
    out = np.zeros((n, 1), dtype=float)
    ok = False
    for sp, p in [('train', CONFIG['embedding_train']), ('val', CONFIG['embedding_val']), ('test', CONFIG['embedding_test'])]:
        if os.path.exists(p) and masks[sp].sum() > 0:
            arr = np.load(p)
            if dims is None:
                dims = arr.shape[1]
                out = np.zeros((n, dims), dtype=float)
            if arr.shape[0] == masks[sp].sum():
                out[masks[sp], :] = arr
                ok = True
    if ok:
        return out
    # fallback: try single latent file if provided (not in config, but maintain safety)
    single_path = os.path.join(CONFIG['model_dir'], "latent_all.npy")
    if os.path.exists(single_path):
        arr = np.load(single_path)
        if arr.shape[0] == n:
            return arr
    # last resort: PCA on expression to obtain a placeholder embedding
    X = adata.X.toarray() if sp.issparse(adata.X) else np.asarray(adata.X)
    pca = PCA(n_components=min(32, X.shape[1]), random_state=42)
    return pca.fit_transform(X)

def per_domain_standardize_train_stats(X, domains, mask_anchor):
    X_out = X.copy()
    for d in np.unique(domains):
        idx_all = (domains == d)
        idx_tr = idx_all & mask_anchor
        if np.sum(idx_tr) == 0:
            continue
        mu = X[idx_tr].mean(axis=0)
        sd = X[idx_tr].std(axis=0, ddof=0)
        sd[sd == 0] = 1.0
        X_out[idx_all] = (X[idx_all] - mu) / sd
    return X_out

def build_variants(X, splits, domains):
    mask_anchor = (splits == 'train') | (splits == 'val')
    scaler = StandardScaler(with_mean=True, with_std=True)
    X_std = X.copy()
    if np.sum(mask_anchor) > 0:
        X_std[mask_anchor] = scaler.fit_transform(X[mask_anchor])
        X_std[~mask_anchor] = scaler.transform(X[~mask_anchor])
    else:
        X_std = scaler.fit_transform(X)
    variants = {}
    # global
    variants['global'] = {
        'X_euc': X_std.copy(),
        'X_cos': row_l2_normalize(X_std.copy())
    }
    # per-domain using anchor stats
    try:
        X_dom = per_domain_standardize_train_stats(X_std, domains, mask_anchor)
        variants['domain'] = {
            'X_euc': X_dom.copy(),
            'X_cos': row_l2_normalize(X_dom.copy())
        }
    except Exception:
        pass
    # whitening keeping >=95% var (fit on anchors)
    try:
        Xa = X_std[mask_anchor] if np.sum(mask_anchor) > 0 else X_std
        pca = PCA(whiten=True, random_state=42)
        Z_anchor = pca.fit_transform(Xa)
        if hasattr(pca, "explained_variance_ratio_"):
            csum = np.cumsum(pca.explained_variance_ratio_)
            n_keep = int(np.searchsorted(csum, 0.95) + 1)
            n_keep = max(2, min(n_keep, Z_anchor.shape[1]))
        else:
            n_keep = min(32, Z_anchor.shape[1])
        pca_n = PCA(n_components=n_keep, whiten=True, random_state=42)
        pca_n.fit(Xa)
        Z_all = pca_n.transform(X_std)
        variants['whiten'] = {
            'X_euc': Z_all.copy(),
            'X_cos': row_l2_normalize(Z_all.copy())
        }
    except Exception:
        pass
    return variants

def kmeans_labels(X, k, seed):
    if X.shape[0] < 2 or k < 2:
        return np.array(['0'] * X.shape[0], dtype=str)
    km = KMeans(n_clusters=int(k), random_state=int(seed), n_init=10)
    return km.fit_predict(X).astype(str)

def evaluate_kmeans_stability(X_anchor, domains_anchor, metric, k_list, seeds, alpha=0.2):
    # domain leakage penalty via ASW-batch (independent of clustering)
    asw_b = asw_batch(X_anchor, domains_anchor, metric=metric)
    best = None
    history = []
    for k in sorted(set([int(kk) for kk in k_list if kk >= 2])):
        labels_all = []
        sils = []
        for s in seeds:
            try:
                labs = kmeans_labels(X_anchor, k, s)
                labels_all.append(labs)
                sils.append(fast_silhouette(X_anchor, labs, metric=metric))
            except Exception:
                continue
        if len(labels_all) < 2:
            continue
        # stability
        stab = mean_pairwise_ari(labels_all)
        sil_mean = float(np.mean([ss for ss in sils if np.isfinite(ss)])) if len(sils) > 0 else -1.0
        objective = sil_mean - alpha * asw_b
        rec = {
            'k': int(k),
            'silhouette': float(sil_mean),
            'stability': float(stab),
            'asw_batch': float(asw_b),
            'objective': float(objective),
            'metric': metric
        }
        history.append(rec)
        if (best is None) or (objective > best['objective']) or (math.isclose(objective, best['objective']) and stab > best['stability'])):
            best = rec
    return best, history

def mean_pairwise_ari(label_list):
    k = len(label_list)
    if k < 2:
        return 1.0
    s = 0.0
    n = 0
    for i in range(k):
        for j in range(i + 1, k):
            try:
                s += adjusted_rand_score(label_list[i], label_list[j])
            except Exception:
                continue
            n += 1
    return float(s / max(n, 1))

def recursive_split_anchors(Xa, labs_a, metric='euclidean', max_iter=3, sil_threshold=0.1, min_gain=0.01):
    for _ in range(max_iter):
        if len(np.unique(labs_a)) < 1:
            break
        try:
            s_samples = silhouette_samples(Xa, labs_a, metric=metric)
            current_sil = fast_silhouette(Xa, labs_a, metric=metric)
        except Exception:
            break
        improved = False
        for cl in np.unique(labs_a):
            idx = np.where(labs_a == cl)[0]
            if idx.size < 10:
                continue
            med_sil = np.median(s_samples[idx]) if idx.size > 0 else 0.0
            if med_sil >= sil_threshold:
                continue
            Xa_sub = Xa[idx]
            # try 2-means
            try:
                labs_sub = kmeans_labels(Xa_sub, 2, seed=42)
            except Exception:
                continue
            labs_new = labs_a.copy()
            # relabel within cluster
            # assign unique new labels
            new_labels = [f"{cl}.0", f"{cl}.1"]
            for t, sub_lab in enumerate(np.unique(labs_sub)):
                labs_new[idx[labs_sub == sub_lab]] = new_labels[t]
            new_sil = fast_silhouette(Xa, labs_new, metric=metric)
            if new_sil >= current_sil + min_gain:
                labs_a = labs_new
                improved = True
                break
        if not improved:
            break
    # reindex labels to compact integers as strings
    uniq = np.unique(labs_a)
    mapping = {u: str(i) for i, u in enumerate(uniq)}
    return np.array([mapping[u] for u in labs_a], dtype=str)

def choose_k_and_temperature_for_propagation(Xa, labs_a, metric='euclidean', k_grid=(5,10,15,20,30,40), T_grid=(0.25,0.5,1.0,2.0)):
    # choose k by maximizing neighbor purity on anchors
    if Xa.shape[0] < 3:
        return 5, 1.0
    if metric == 'cosine':
        Xa_use = row_l2_normalize(Xa)
    else:
        Xa_use = Xa
    best_k = None
    best_purity = -1.0
    for k in k_grid:
        k = max(1, min(int(k), Xa_use.shape[0]-1))
        try:
            nn = NearestNeighbors(n_neighbors=k+1, metric=metric).fit(Xa_use)
            dist, idx = nn.kneighbors(Xa_use, return_distance=True)
            idx = idx[:, 1:]  # exclude self
            neigh_labs = np.array(labs_a)[idx]
            same = (neigh_labs == np.array(labs_a)[:, None]).mean(axis=1)
            purity = float(np.mean(same))
            if (purity > best_purity) or (math.isclose(purity, best_purity) and (best_k is None or k < best_k)):
                best_purity = purity
                best_k = int(k)
        except Exception:
            continue
    if best_k is None:
        best_k = 15
    # choose temperature by maximizing soft self-consistency
    best_T = None
    best_score = -1.0
    try:
        nn = NearestNeighbors(n_neighbors=min(best_k+1, Xa_use.shape[0]), metric=metric).fit(Xa_use)
        dist, idx = nn.kneighbors(Xa_use, return_distance=True)
        idx = idx[:, 1:]
        dist = dist[:, 1:]
        for T in T_grid:
            if metric == 'cosine':
                sim = 1.0 - dist
            else:
                sim = 1.0 / (1e-8 + dist)
            w = sim / (T + 1e-8)
            w = np.exp(w - w.max(axis=1, keepdims=True))
            w = w / (w.sum(axis=1, keepdims=True) + 1e-12)
            neigh_labs = np.array(labs_a)[idx]
            uniq = np.unique(labs_a)
            lab_to_col = {lab: i for i, lab in enumerate(uniq)}
            P = np.zeros((Xa_use.shape[0], len(uniq)), dtype=float)
            for i in range(Xa_use.shape[0]):
                for j, lab in enumerate(neigh_labs[i]):
                    P[i, lab_to_col[lab]] += w[i, j]
            pred = np.array([uniq[np.argmax(P[i])] for i in range(Xa_use.shape[0])], dtype=object)
            score = (pred == np.array(labs_a)).mean()
            if score > best_score:
                best_score = float(score)
                best_T = float(T)
    except Exception:
        best_T = 1.0
    if best_T is None:
        best_T = 1.0
    return int(best_k), float(best_T)

def soft_label_propagation(X_anchor, labs_anchor, X_query, metric='euclidean', k=15, temperature=1.0):
    if X_query.shape[0] == 0 or X_anchor.shape[0] == 0:
        return np.array([], dtype=str)
    if metric == 'cosine':
        Xa = row_l2_normalize(X_anchor)
        Xq = row_l2_normalize(X_query)
    else:
        Xa = X_anchor
        Xq = X_query
    k = max(1, min(int(k), Xa.shape[0]))
    nn = NearestNeighbors(n_neighbors=k, metric=metric)
    nn.fit(Xa)
    dist, idx = nn.kneighbors(Xq, return_distance=True)
    if metric == 'cosine':
        sim = 1.0 - dist
    else:
        sim = 1.0 / (1e-8 + dist)
    w = sim / (float(temperature) + 1e-8)
    w = np.exp(w - w.max(axis=1, keepdims=True))
    w = w / (w.sum(axis=1, keepdims=True) + 1e-12)
    uniq = np.unique(labs_anchor)
    lab_to_col = {lab: i for i, lab in enumerate(uniq)}
    P = np.zeros((Xq.shape[0], len(uniq)), dtype=float)
    labs_anchor = np.array(labs_anchor, dtype=object)
    for i in range(Xq.shape[0]):
        for j, ai in enumerate(idx[i]):
            P[i, lab_to_col[labs_anchor[ai]]] += w[i, j]
    pred = np.array([uniq[np.argmax(P[i])] for i in range(Xq.shape[0])], dtype=str)
    return pred

def merge_small_clusters_safe(X_all, labs_all, mask_anchor, metric='cosine'):
    # scale min_size with n
    n = X_all.shape[0]
    min_size = max(15, int(round(0.003 * n)))
    labs = np.array(labs_all, dtype=str)
    uniq, counts = np.unique(labs, return_counts=True)
    small = [u for u, c in zip(uniq, counts) if c < min_size]
    if len(small) == 0:
        return labs
    # compute centroids (use metric geometry)
    def centroid(X):
        c = X.mean(axis=0)
        if metric == 'cosine':
            c = c / (norm(c) + 1e-12)
        return c
    # precompute anchor silhouettes
    try:
        Xa = X_all[mask_anchor]
        la = labs[mask_anchor]
        sil_a = silhouette_samples(Xa, la, metric=metric)
        sil_map = {lab: sil_a[la == lab] for lab in np.unique(la)}
    except Exception:
        sil_map = {lab: np.array([0.0]) for lab in np.unique(labs[mask_anchor])}
    # large clusters
    large = [u for u in uniq if u not in small]
    if len(large) == 0:
        return labs
    centers = {u: centroid(X_all[labs == u]) for u in large}
    for sc in small:
        idx_sc = np.where(labs == sc)[0]
        # require median anchor silhouette non-positive
        med_sil = float(np.median(sil_map.get(sc, np.array([0.0]))))
        if med_sil > 0.0:
            continue
        cen_sc = centroid(X_all[idx_sc])
        # find nearest large by cosine/euclidean distance
        dists = []
        for lg in large:
            cen_lg = centers[lg]
            if metric == 'cosine':
                sim = float(np.dot(cen_sc, cen_lg) / (norm(cen_sc) * norm(cen_lg) + 1e-12))
                d = 1.0 - sim
            else:
                d = float(norm(cen_sc - cen_lg))
            dists.append((d, lg))
        dists.sort(key=lambda x: x[0])
        if len(dists) == 0:
            continue
        d_near, target = dists[0]
        # compute target intra distances to its centroid among anchors
        idx_ta = np.where((labs == target) & mask_anchor)[0]
        if idx_ta.size < 5:
            continue
        cen_t = centers[target]
        if metric == 'cosine':
            sims = (X_all[idx_ta] @ cen_t) / ((norm(X_all[idx_ta], axis=1) * norm(cen_t)) + 1e-12)
            intra = 1.0 - sims
        else:
            intra = norm(X_all[idx_ta] - cen_t, axis=1)
        thr = float(np.percentile(intra, 90))
        # merge only if inter-centroid distance <= threshold
        if d_near <= thr:
            labs[idx_sc] = target
    return labs

def load_prior_artifacts():
    try:
        S = load_sparse_csr(CONFIG['set_incidence'])
        set_meta = pd.read_csv(CONFIG['set_meta'])
        gene_vocab = pd.read_csv(CONFIG['gene_vocab'])
        return S, set_meta, gene_vocab
    except Exception:
