def compute_deg(ad_all, labs_all, genes_include_mask, gene_vocab):
    # Use per-cell log1p for DE; filter out non-informative genes via gene_vocab
    X = ad_all.layers['log1p'] if 'log1p' in ad_all.layers else (ad_all.X)
    X = X.toarray() if sp.issparse(X) else np.asarray(X)
    var_names = ad_all.var_names.to_numpy().astype(str)
    labs = np.array(labs_all, dtype=str)
    uniq = np.unique(labs)
    # Exclusions
    excl = np.zeros(var_names.shape[0], dtype=bool)
    try:
        gv = gene_vocab.set_index('symbol')
        cols = ['is_mito', 'is_ribo', 'is_housekeeping']
        for c in cols:
            if c in gv.columns:
                m = var_names.astype(object)
                flags = gv.reindex(m)[c].fillna(False).to_numpy().astype(bool)
                excl |= flags
    except Exception:
        pass
    base_mask = (~excl)
    if genes_include_mask is not None:
        base_mask = base_mask & genes_include_mask
    top_degs = {}
    all_sig_degs = {}
    for cl in uniq:
        idx_in = np.where(labs == cl)[0]
        idx_out = np.where(labs != cl)[0]
        if idx_in.size < 3 or idx_out.size < 3:
            top_degs[str(cl)] = []
            all_sig_degs[str(cl)] = []
            continue
        mu_in = X[idx_in].mean(axis=0)
        mu_out = X[idx_out].mean(axis=0)
        pct_in = (X[idx_in] > 0).mean(axis=0)
        pct_out = (X[idx_out] > 0).mean(axis=0)
        log2fc = np.log2((mu_in + 1e-9) / (mu_out + 1e-9))
        pvals = np.ones(X.shape[1], dtype=float)
        try:
            for j in np.where(base_mask)[0]:
                try:
                    stat = mannwhitneyu(X[idx_in, j], X[idx_out, j], alternative='two-sided', method='auto')
                    pvals[j] = float(stat.pvalue)
                except TypeError:
                    _, pv = mannwhitneyu(X[idx_in, j], X[idx_out, j], alternative='two-sided')
                    pvals[j] = float(pv)
        except Exception:
            pass
        qvals = bh_fdr(pvals)
        sig = (qvals < 0.05) & (pct_in >= 0.2) & ((pct_in - pct_out) >= 0.1) & (log2fc >= 0.25) & base_mask
        sig_idx = np.where(sig)[0]
        if sig_idx.size == 0:
            # fallback: top by log2fc among included
            cand = np.where(base_mask)[0]
            order = cand[np.argsort(-log2fc[cand])]
            genes = var_names[order][:20].tolist()
            top_degs[str(cl)] = genes
            all_sig_degs[str(cl)] = []
        else:
            order = sig_idx[np.argsort(-log2fc[sig_idx])]
            genes = var_names[order][:20].tolist()
            top_degs[str(cl)] = genes
            all_sig_degs[str(cl)] = var_names[sig_idx].tolist()
    return top_degs, all_sig_degs

def compute_set_activities(ad_all, labs_all, S, set_meta):
    # Prefer model-provided set activities; else compute from expression
    n = ad_all.n_obs
    use_model = False
    set_scores = None
    if os.path.exists(CONFIG['set_activity_train']) and os.path.exists(CONFIG['set_activity_val']) and os.path.exists(CONFIG['set_activity_test']):
        splits = ad_all.obs['split'].astype(str).values if 'split' in ad_all.obs.columns else np.array(['all'] * n)
        mask_tr = (splits == 'train')
        mask_va = (splits == 'val')
        mask_te = (splits == 'test')
        A_tr = np.load(CONFIG['set_activity_train'])
        A_va = np.load(CONFIG['set_activity_val'])
        A_te = np.load(CONFIG['set_activity_test'])
        n_sets = A_tr.shape[1]
        set_scores = np.zeros((n, n_sets), dtype=float)
        if A_tr.shape[0] == mask_tr.sum():
            set_scores[mask_tr, :] = A_tr
        if A_va.shape[0] == mask_va.sum():
            set_scores[mask_va, :] = A_va
        if A_te.shape[0] == mask_te.sum():
            set_scores[mask_te, :] = A_te
        use_model = True
    if not use_model:
        # compute from expression using S and all prior-in-vocab genes
        if S is None or set_meta is None:
            return None
        X = ad_all.layers['log1p'] if 'log1p' in ad_all.layers else ad_all.X
        if sp.issparse(X):
            X = X.tocsr()
        else:
            X = sp.csr_matrix(np.asarray(X))
        # Map adata genes to S columns using gene symbols
        # Assume S columns order matches gene_vocab symbols saved; we cannot remap here robustly without gene_vocab index, handled upstream
        # We will align by overlapping genes via gene_vocab
        try:
            gv = pd.read_csv(CONFIG['gene_vocab'])
            symbol_to_idx = {g: i for i, g in enumerate(gv['symbol'].astype(str).values)}
            ad_syms = ad_all.var_names.to_numpy().astype(str)
            mapped = np.array([symbol_to_idx.get(g, -1) for g in ad_syms], dtype=int)
            valid = mapped >= 0
            cols = mapped[valid]
            if cols.size == 0:
                return None
            S_sub = S[:, cols].tocsr()
            row_sums = np.array(S_sub.sum(axis=1)).ravel()
            row_sums[row_sums == 0] = 1.0
            inv = sp.diags(1.0 / row_sums)
            S_sub = inv.dot(S_sub)
            X_sub = X[:, np.where(valid)[0]]
            set_scores = X_sub.dot(S_sub.T).toarray()
        except Exception:
            return None
    labs = np.array(labs_all, dtype=str)
    uniq = np.unique(labs)
    set_results = {}
    for cl in uniq:
        idx_in = np.where(labs == cl)[0]
        idx_out = np.where(labs != cl)[0]
        if idx_in.size < 3 or idx_out.size < 3:
            set_results[str(cl)] = []
            continue
        in_means = set_scores[idx_in].mean(axis=0)
        out_means = set_scores[idx_out].mean(axis=0)
        diff = np.asarray(in_means - out_means).ravel()
        pos = np.where(diff > 0)[0]
        if pos.size == 0:
            set_results[str(cl)] = []
            continue
        order = pos[np.argsort(-diff[pos])]
        # significance/AUC
        p = np.ones(set_scores.shape[1], dtype=float)
        aucs = np.full(set_scores.shape[1], 0.5, dtype=float)
        for j in order[:min(200, order.size)]:
            try:
                stat = mannwhitneyu(set_scores[idx_in, j], set_scores[idx_out, j], alternative='two-sided', method='auto')
                p[j] = float(stat.pvalue)
            except TypeError:
                _, pv = mannwhitneyu(set_scores[idx_in, j], set_scores[idx_out, j], alternative='two-sided')
                p[j] = float(pv)
            try:
                u_lr = mannwhitneyu(set_scores[idx_in, j], set_scores[idx_out, j], alternative='less').statistic
                aucs[j] = float(u_lr) / float(len(idx_in) * len(idx_out))
            except Exception:
                a = set_scores[idx_in, j]
                b = set_scores[idx_out, j]
                rs_in = a if a.size * b.size <= 50000 else np.random.choice(a, size=min(a.size, 200), replace=False)
                rs_out = b if a.size * b.size <= 50000 else np.random.choice(b, size=min(b.size, 200), replace=False)
                aucs[j] = float((rs_in[:, None] > rs_out[None, :]).mean())
        q = bh_fdr(p)
        enriched = np.where((diff > 0) & (q < 0.05) & (aucs >= 0.6))[0]
        if enriched.size == 0:
            set_results[str(cl)] = []
            continue
        # sort by effect then q
        ord2 = enriched[np.lexsort((q[enriched], -diff[enriched]))]
        top_idx = ord2[:10]
        rows = []
        for j in top_idx:
            sid = int(set_meta.iloc[j].get('set_id', j)) if 'set_id' in set_meta.columns else int(j)
            name = str(set_meta.iloc[j].get('name', f'set_{j}'))
            src = str(set_meta.iloc[j].get('source', 'NA'))
            cat = str(set_meta.iloc[j].get('category', 'NA'))
            fdr = float(max(min(q[j], 1.0), 1e-300))
            eff = float(diff[j])
            auc = float(aucs[j])
            rows.append({'set_id': sid, 'name': name, 'source': src, 'category': cat, 'fdr': fdr, 'effect_size': eff, 'auc': auc})
        set_results[str(cl)] = rows
    return set_results

def marker_concordance(all_sig_degs, S, set_meta, ad_all):
    if S is None or set_meta is None:
        return {k: [] for k in all_sig_degs.keys()}
    # Build set memberships by symbols present in adata
    try:
        gv = pd.read_csv(CONFIG['gene_vocab'])
        symbol_to_idx = {g: i for i, g in enumerate(gv['symbol'].astype(str).values)}
        ad_syms = ad_all.var_names.to_numpy().astype(str)
        mapped = np.array([symbol_to_idx.get(g, -1) for g in ad_syms], dtype=int)
        valid = mapped >= 0
        cols = mapped[valid]
        if cols.size == 0:
            return {k: [] for k in all_sig_degs.keys()}
        S_sub = S[:, cols].tocsr()
        ad_syms_present = ad_syms[valid]
        set_members = []
        for i in range(S_sub.shape[0]):
            row = S_sub.getrow(i)
            genes_i = set(ad_syms_present[row.indices].tolist())
            set_members.append(genes_i)
        # marker indices
        mk_mask = np.array([(str(src).lower() == 'cellmarker') or (str(cat).lower() == 'marker')
                            for src, cat in zip(set_meta.get('source', ['']*S_sub.shape[0]),
                                                set_meta.get('category', ['']*S_sub.shape[0]))])
        mk_idx = np.where(mk_mask)[0].tolist()
        out = {}
        for cl, genes in all_sig_degs.items():
            gset = set(genes)
            rows = []
            if len(gset) > 0:
                for j in mk_idx:
                    inter = gset & set_members[j]
                    union = gset | set_members[j]
                    if len(inter) == 0:
                        continue
                    jac = (len(inter) / float(len(union))) if len(union) > 0 else 0.0
                    rows.append({
                        'set_id': int(set_meta.iloc[j].get('set_id', j)) if 'set_id' in set_meta.columns else int(j),
                        'name': str(set_meta.iloc[j].get('name', f'set_{j}')),
                        'jaccard': float(jac),
                        'overlap_genes': sorted(list(inter))
                    })
            rows = sorted(rows, key=lambda x: (-x['jaccard'], x['name']))[:5]
            out[cl] = rows
        return out
    except Exception:
        return {k: [] for k in all_sig_degs.keys()}

